import { TonalPalette, hexFromArgb } from '@material/material-color-utilities';

/** Seed colours the user can pick. The Material 3 palette itself is generated by <m3e-theme>. */
export interface Seed { id: string; hex: string }

export const SEEDS: Seed[] = [
  { id: 'teal', hex: '#00897B' },
  { id: 'blue', hex: '#3F6FD1' },
  { id: 'violet', hex: '#6750A4' },
  { id: 'rose', hex: '#C2467A' },
  { id: 'orange', hex: '#D2691E' },
  { id: 'green', hex: '#4C8C2B' },
];
export const seedById = (id: string) => SEEDS.find(s => s.id === id) ?? SEEDS[0];

/** Colour styles supported by <m3e-theme>. */
export const COLOR_STYLES = ['tonal-spot', 'vibrant', 'expressive', 'fidelity', 'neutral', 'monochrome', 'rainbow', 'fruit-salad'] as const;
export type ColorStyle = (typeof COLOR_STYLES)[number];
export type Contrast = 'standard' | 'medium' | 'high';

/**
 * Colours Material 3 does not define: success, warning and the category tiles. They come from the same HCT tonal
 * palettes the theme uses, so they match its light and dark tones.
 */
export function customColors(dark: boolean): Record<string, string> {
  const tone = (hue: number, chroma: number, t: number) => hexFromArgb(TonalPalette.fromHueAndChroma(hue, chroma).tone(t));
  const [main, onMain, container, onContainer] = dark ? [80, 20, 30, 90] : [40, 100, 90, 10];
  const out: Record<string, string> = {
    '--success': tone(145, 42, main), '--success-container': tone(145, 42, container), '--on-success-container': tone(145, 42, onContainer),
    '--warning': tone(75, 48, main), '--on-warning': tone(75, 48, onMain), '--warning-container': tone(75, 48, container), '--on-warning-container': tone(75, 48, onContainer),
  };
  [300, 80, 250, 160, 355, 230].forEach((hue, i) => {
    const chroma = i === 5 ? 6 : 26;
    out[`--t${i + 1}-bg`] = tone(hue, chroma, dark ? 30 : 90);
    out[`--t${i + 1}-fg`] = tone(hue, chroma, dark ? 90 : 10);
  });
  return out;
}
